import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"Lab Word Documentation","description":"","frontmatter":{"docLocale":"en","counterpart":"/docs/","contentType":"overview","prev":false,"next":{"text":"Quick start","link":"/en/getting-started/quickstart"}},"headers":[],"relativePath":"en/docs/index.md","filePath":"en/docs/index.md"}'),i={name:"en/docs/index.md"};function o(d,e,s,c,l,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="lab-word-documentation" tabindex="-1">Lab Word Documentation <a class="header-anchor" href="#lab-word-documentation" aria-label="Permalink to &quot;Lab Word Documentation&quot;">​</a></h1><p>Lab Word is a laboratory digital twin. Current work establishes a Three.js presentation layer for equipment models; placement and live state follow later.</p><h2 id="choose-your-task" tabindex="-1">Choose Your Task <a class="header-anchor" href="#choose-your-task" aria-label="Permalink to &quot;Choose Your Task&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Starting point</th><th>Observable result</th></tr></thead><tbody><tr><td>Start the existing application</td><td><a href="./../getting-started/quickstart">Quick start</a></td><td>Ready API and accessible Web registration page</td></tr><tr><td>Inspect equipment models</td><td><a href="./../guides/lab-viewer">Lab Viewer preview</a></td><td>A rendered model and local GLB import in an isolated preview</td></tr><tr><td>Change the project</td><td><a href="./../architecture/project-structure">Project structure</a></td><td>Locate application composition and business ownership</td></tr><tr><td>Look up interfaces</td><td><a href="./../reference/api">API</a> and <a href="./../reference/config">configuration</a></td><td>Find generated contracts and defaults</td></tr></tbody></table><h2 id="current-capabilities-and-plans" tabindex="-1">Current Capabilities And Plans <a class="header-anchor" href="#current-capabilities-and-plans" aria-label="Permalink to &quot;Current Capabilities And Plans&quot;">​</a></h2><p>The application already has identity, membership, knowledge, files and jobs through its <a href="./../guides/platform">platform capabilities</a>. Lab Viewer v1 runs independently and its visual experience is accepted. Acceptance of production routing, the Lab entry after login and production lazy loading is pending.</p><p>Local GLB import stays in the browser session and does not upload files. Equipment data integration, control and scene placement follow later. <a href="./../architecture/lab-word">Product scope</a> explains the boundary; the <a href="https://github.com/CaiZongyuan/labworld/blob/c79e3553922becff92cc876ed71a7babc05d16a7/docs/plans/lab-viewer-m0.md" target="_blank" rel="noreferrer">presentation plan</a> records future acceptance criteria.</p><h2 id="reading-and-maintenance" tabindex="-1">Reading And Maintenance <a class="header-anchor" href="#reading-and-maintenance" aria-label="Permalink to &quot;Reading And Maintenance&quot;">​</a></h2><p>Tutorials grow the same Lab business code. Independent guides provide a task, prerequisites, source locations, commands, results and failure boundaries. Existing capabilities, previews and plans carry distinct status statements.</p><p>Chinese and English pages are paired by chapter. API and configuration facts are generated from implementation. Update relevant documentation and <a href="./../testing/feedback-loop">validation</a> with behavior changes; see <a href="./../guides/documentation">documentation maintenance</a>.</p><hr><p>Source version：<code>c79e3553922b</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/c79e3553922becff92cc876ed71a7babc05d16a7/docs/getting-started/documentation.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',12)])])}const b=a(i,[["render",o]]);export{h as __pageData,b as default};
